WITH metrics AS (SELECT *, LEAD(shipping_fee) OVER (PARTITION BY customer_id ORDER BY amount, id) AS next_shipping_fee, LAG(shipping_fee) OVER (PARTITION BY customer_id ORDER BY amount, id) AS prev_shipping_fee, LEAD(amount) OVER (PARTITION BY customer_id ORDER BY amount, id) AS next_amount, LAG(amount) OVER (PARTITION BY customer_id ORDER BY amount, id) AS prev_amount, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount, id) AS seq_no FROM orders WHERE customer_id = 18), not_flagged AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM shipments x WHERE x.order_id = s.id AND x.shipped_date >= s.order_date)), eligible AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM shipments x WHERE x.order_id = s.id AND x.cost < 45)), scored AS (SELECT id, customer_id, store_id, order_date, status, next_amount, prev_amount, DENSE_RANK() OVER (PARTITION BY store_id ORDER BY prev_shipping_fee DESC NULLS FIRST) AS prev_shipping_fee_dense_rank, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY shipping_fee, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount, id) AS row_seq FROM eligible) SELECT id, store_id, order_date, status, prev_amount, prev_shipping_fee_dense_rank, event_seq, row_seq, CASE WHEN status RLIKE '^(SHIPPED|PENDING)$' THEN 'CORE' ELSE 'GROUP_A' END AS status_zone FROM scored ORDER BY event_seq DESC, order_date;
